import "./Services.css";

function Services() {
  return (
    <div className="services">
      <h2>Our Services</h2>
      <div className="service-cards">
        <div className="card">2-Wheeler Driving Training</div>
        <div className="card">4-Wheeler Driving Training</div>
        <div className="card">Fast Tag</div>
        <div className="card">License Renewal</div>
        <div className="card">Vehicle Passing</div>
        <div className="card">Other Driving Courses</div>
      </div>
    </div>
  );
}

export default Services;
